-- 0168: plurals, Lane-marker sweep (pl.) — sources for the 8 Qurʾānic plurals, 6 book plurals not in the Qurʾān.
-- jam2: plurals (ar_ling_root_lemma_jam, 200-LEM) of the 13 lemmas of Ghāfir 40:1–3 — second pass on 0137/0138.
-- 1. Audit of the live rows: each gets its Lane line (lane_ref = block id + page, lane_quote_en verbatim) and its
--    Arabic-book lines. lexicon_fact_ids_json now holds the BOOK LINES themselves:
--    [{"source":<slug>,"block_id":<lexicon block>,"page":<printed page>,"quote":<verbatim>}] (the worker does not read
--    this column; 0138 had ar_ling_lexicon_fact ids here, several of which were found wrong).
-- 2. Lemmas with no plural yet (تَنزِيل، قَابِل، تَوْب، عِقَاب، طَوْل، مَصِير) searched in Lane ("pl.") and the Arabic
--    books (والجمع، جمعه، ج:، جمع).
-- 3. Book-stated plurals of the live lemmas that the Qurʾān does not use → in_quran = 0, no verse, note "Not in the Qurʾān.".
-- Every quote was checked against its block through ar_ling_root_lexicon_block_v (tashkīl stripped); every needle
-- against qr_ayah.text_uthmani (bare). Guarded UPDATEs (only touch a row still in its 0138 shape); INSERT OR IGNORE.

-- كِتَاب → كُتُب (live, 98:3). Lane already right (checked). Book lines: Ṣiḥāḥ p.404, Lisān p.698. كُتْب (same letters) is the lighter reading of the same plural — cannot be its own row (UNIQUE plural_bare); noted.
UPDATE ar_ling_root_lemma_jam SET lexicon_fact_ids_json = '[{"source": "jawhari_sihah", "block_id": "blk_sih_e0be950f6e20320c", "page": 404, "quote": "الكتاب معروف، والجمع كُتُبٌ وكُتْبٌ."}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_636ebe57fbbd84d9", "page": 698, "quote": "الكِتابُ: مَعْرُوفٌ، وَالْجَمْعُ كُتُبٌ وكُتْبٌ."}]' WHERE id = 'JAM:26ec9894256ccd2fcb77820470:كتب' AND lemma_id = '26ec9894256ccd2fcb77820470' AND plural_bare = 'كتب' AND (lexicon_fact_ids_json IS NULL OR lexicon_fact_ids_json NOT LIKE '[{%');
UPDATE ar_ling_root_lemma_jam SET note_en = 'Also 2:285, 4:136, 21:104, 34:44, 66:12. Also said كُتْب (same plural, lighter vowel; not in the Qurʾān). No plural of few (Sībawayh, in al-Muḥkam): ثلاثة كتب.' WHERE id = 'JAM:26ec9894256ccd2fcb77820470:كتب' AND lemma_id = '26ec9894256ccd2fcb77820470' AND plural_bare = 'كتب' AND (note_en NOT LIKE '%كُتْب%');

-- ذَنْب → ذُنُوب (live, 39:53). Lane already right (checked). Book lines: Lisān p.389, Miṣbāḥ p.1068, al-ʿAyn p.2961, Mufradāt p.331.
UPDATE ar_ling_root_lemma_jam SET lexicon_fact_ids_json = '[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_c31c39ad6009585e", "page": 389, "quote": "الذَّنْبُ: الإِثْمُ والجُرْمُ وَالْمَعْصِيَةُ، والجمعُ ذُنوبٌ، وذُنُوباتٌ جمعُ الْجَمْعِ"}, {"source": "fayyumi_misbah_munir", "block_id": "blk_msb_58e51138960d96fe", "page": 1068, "quote": "الذَّنْبُ الْإِثْمُ وَالْجَمْعُ ذُنُوبٌ"}, {"source": "khalil_kitab_ayn", "block_id": "blk_kay_027e544a5013b5bf", "page": 2961, "quote": "والذَّنْب: الإِثْمُ والمَعصِية، والجمع الذُّنُوب."}, {"source": "raghib_mufradat", "block_id": "blk_mfr_4913f32df599d194", "page": 331, "quote": "وجمع الذّنب ذُنُوب"}]' WHERE id = 'JAM:2e7a23ca384799c20b92778cf7:ذنوب' AND lemma_id = '2e7a23ca384799c20b92778cf7' AND plural_bare = 'ذنوب' AND (lexicon_fact_ids_json IS NULL OR lexicon_fact_ids_json NOT LIKE '[{%');
-- ذَنْب → ذُنُوبَات, plural of the plural (Lisān, Tāj, Lane). Not in the Qurʾān (qr_ayah text_bare: 0 hits).
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, plural_lemma_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:2e7a23ca384799c20b92778cf7:ذنوبات', '2e7a23ca384799c20b92778cf7', 'ذُنُوبَاتٌ', 'ذنوبات', 'GT:noun_process:jam_muannath_salim', NULL, NULL, 0, NULL, NULL, NULL, NULL, '[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_c31c39ad6009585e", "page": 389, "quote": "والجمعُ ذُنوبٌ، وذُنُوباتٌ جمعُ الْجَمْعِ"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_936c22e9b28ae8e7", "page": 436, "quote": "(الجَمْعُ: ذُنُوبٌ، وجج) أَي جَمْعُ الجَمْعِ (ذُنُوبَاتٌ"}]', 'blk_lane_38a70932e87987f8 p.980', 'pl. ذُنُوبٌ (M, Msb, K) and pl. pl. ذُنُوبَاتٌ. (M, K.)', 'Not in the Qurʾān. A plural of the plural ذُنُوب.', 2);

-- عَزِيز → أَعِزَّة (live, 5:54; also 27:34). Gap filled: Arabic book lines (Ṣiḥāḥ p.1751, Lisān p.2958, Miṣbāḥ p.2023); Lane quote made verbatim (0138 had «…»).
UPDATE ar_ling_root_lemma_jam SET lexicon_fact_ids_json = '[{"source": "jawhari_sihah", "block_id": "blk_sih_249b69cb8b3620ad", "page": 1751, "quote": "وجمع العزيز عِزازٌ، مثل كريم وكرام. وقوم أعزَّةٌ وأعِزَّاءُ"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_7faccc5ba1b9c2fe", "page": 2958, "quote": "وَرَجُلٌ عَزيزٌ مِنْ قَوْمٍ أَعِزَّة وأَعِزَّاء وعِزازٍ"}, {"source": "fayyumi_misbah_munir", "block_id": "blk_msb_1ebb65d597866856", "page": 2023, "quote": "فَهُوَ عَزِيزٌ وَجَمْعُهُ أَعِزَّةٌ"}]' WHERE id = 'JAM:3d42f257c274c5d8463f1b8371:اعزه' AND lemma_id = '3d42f257c274c5d8463f1b8371' AND plural_bare = 'اعزه' AND (lexicon_fact_ids_json IS NULL OR lexicon_fact_ids_json NOT LIKE '[{%');
UPDATE ar_ling_root_lemma_jam SET lane_quote_en = 'the pl. of عَزِيزٌ is عِزَازٌ (Ṣ, O, Ḳ) and أَعِزَّةٌ (Ṣ, Mṣb, Ḳ) and أَعِزَّآءُ; (Ṣ, Ḳ;)', note_en = 'Also 27:34. The books also give عِزَاز and أَعِزَّاء (see their rows).' WHERE id = 'JAM:3d42f257c274c5d8463f1b8371:اعزه' AND lemma_id = '3d42f257c274c5d8463f1b8371' AND plural_bare = 'اعزه' AND (lane_quote_en LIKE '%…%');
