-- غَافِر → غَافِرُونَ (live, 7:155). No book line and no Lane "pl." line exists for it (searched all غفر blocks; غُفُر is the plural of غَفُور, a different word). Sources stay empty; the note says so.
UPDATE ar_ling_root_lemma_jam SET note_en = 'No book states this plural; it is the regular -ūn plural, which every such adjective takes. Lane (p.2274) gives غَافِر with no plural.' WHERE id = 'JAM:ea923679f32861b46d50eade95:غافرون' AND lemma_id = 'ea923679f32861b46d50eade95' AND plural_bare = 'غافرون' AND (note_en LIKE 'The regular sound plural%');

-- قَابِل → قَبَلَة. Lisān p.1132 and Tāj p.221 give it right after «القابل: the one who takes the bucket» (blocks in sequence: Lisān seq 1015→1016 verse→1017; Tāj seq 55→56→57). Lane gives no plural of قَابِل. Not in the Qurʾān (the only قبلة there is قِبْلَة, the prayer direction — another word). Pattern فَعَلَة is new.
INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:faala_pl', 'faala_pl', 'فَعَلَة', 'jam_taksir', 'jam', 'faʿala (plural)', 300, 'Broken plural pattern.', 'live');
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, plural_lemma_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:89060f9f3668b069e4ca2ada7a:قبله', '89060f9f3668b069e4ca2ada7a', 'قَبَلَةٌ', 'قبله', 'GT:noun_process:jam_taksir', 'WZ:faala_pl', NULL, 0, NULL, NULL, NULL, NULL, '[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_e6e87e79c3231636", "page": 1132, "quote": "والقابِل: الَّذِي يَقْبَل الدَّلْوَ"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_219bbaf6bc5b509f", "page": 1132, "quote": "وَالْجَمْعُ قَبَلَة، وَقَدْ قَبِلها قَبُولًا"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_4b64f7e1d2ec347a", "page": 221, "quote": "وَهُوَ أَي القابِلُ الَّذِي يأخذُها من الساقي، وضِدُّه الدّابِرُ"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_9fc74c57617ae041", "page": 221, "quote": "والجمعُ قَبَلَةٌ، وَقد قَبِلَها قَبُولاً"}]', NULL, NULL, 'Not in the Qurʾān. The books give it for قَابِل as the man at the well who takes the bucket.', 1);

-- مَصِير → مَصَايِر. Only Lane states it (p.1755, under مَصِيرٌ, sense «a place of herbage and water», citing al-Asās). No Arabic book in the corpus gives a plural of مَصِير (searched all صير blocks for مصاير/مصائر/والجمع). Not in the Qurʾān (qr_ayah text_bare: 0 hits). Pattern مَفَاعِل is new.
INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:mafail_pl', 'mafail_pl', 'مَفَاعِل', 'jam_taksir', 'jam', 'mafāʿil (plural)', 300, 'Broken plural pattern.', 'live');
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, plural_lemma_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:a6a5a940211be758e1edae8a66:مصاير', 'a6a5a940211be758e1edae8a66', 'مَصَايِرُ', 'مصاير', 'GT:noun_process:jam_taksir', 'WZ:mafail_pl', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'blk_lane_bb4e8e4325231ca9 p.1755', '[or a place of herbage, or pasture, and of water: pl. مَصَايِرُ: so in the saying,] خَرَجُوا إِلَى مَصَايِرِهِمْ', 'Not in the Qurʾān. Said of places with water and pasture. Only Lane gives it (from al-Asās); no Arabic book here states it.', 1);

